/**
 * Account identity rules shared by sign-up, sign-in and password reset.
 *
 * ADR 0003 §3: an address is case-insensitive. It is stored and compared in
 * lowercase, whichever way it was typed.
 */

/** The stored and compared form of an email address. */
export function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

/**
 * ADR 0003 §4: an address that already has an account is refused as a
 * `conflict`, and nothing is created.
 */
export class AccountExistsError extends Error {
  readonly code = "conflict" as const;

  constructor() {
    super("An account with that email already exists");
    this.name = "AccountExistsError";
  }
}

