import { consumeRateLimit, RateLimitedError } from "@/lib/rate-limit";
import { SLUG_MIN_LENGTH, slugify, uniqueSlug } from "@/lib/slug";
import { ORGANIZATION_NAME_MAX_LENGTH } from "@/schemas/organization";
