cat > tests/zz-scratch-signup.test.ts <<'EOF'
import { beforeAll, beforeEach, describe, expect, it, vi } from "vitest";
vi.mock("@/server/services/email-service", () => ({
  renderEmail: async () => ({ subject: "s", html: "h", text: "t" }),
  sendEmail: async () => undefined,
}));
import { toAppError } from "@/lib/errors";
import { resetRateLimits } from "@/lib/rate-limit";
import { setupTestDb, resetTestDb } from "../tests/helpers/db";
import * as userRepo from "@/server/repositories/user-repository";
import * as authService from "@/server/services/auth-service";
import { getDb, organizations, users } from "@/server/db";
import { createOrganizationSchema } from "@/schemas/organization";
import { updateOrganizationSchema } from "@/schemas/organization";

const PW = "Correct1Horse2";
const reg = (name: string, email = `${name.length}-${Math.random().toString(36).slice(2)}@ex.com`) =>
  authService.register({ name, email, password: PW, confirmPassword: PW, acceptTerms: true } as never);

beforeAll(async () => { await setupTestDb(); });
beforeEach(async () => { await resetTestDb(); resetRateLimits(); });

describe("scratch sign-up", () => {
  it.each([
    ["Admin", "admin-2"], ["Billing", "billing-2"], ["Support", "support-2"], ["Taskflow", "taskflow-2"],
    ["Al", "al"], ["J", "workspace"], ["山田", "workspace"], ["!!!", "workspace"],
  ])("name %s gets slug %s", async (name, slug) => {
    const { org } = await reg(name);
    expect(org.slug).toBe(slug);
    expect(org.name).toBe(`${name}'s workspace`);
  });

  it("truncates a long name so the workspace name fits the limit", async () => {
    const long = "A".repeat(80);
    const { org } = await reg(long);
    expect(org.name.length).toBe(64);
    expect(org.name.endsWith("'s workspace")).toBe(true);
    expect(createOrganizationSchema.safeParse({ name: org.name, slug: org.slug }).success).toBe(true);
    expect(updateOrganizationSchema.safeParse({ orgId: org.id, name: org.name }).success).toBe(true);
  });

  it("uses a suffix when the slug base is taken", async () => {
    const a = await reg("Acme");
    const b = await reg("Acme");
    expect(a.org.slug).toBe("acme");
    expect(b.org.slug).toBe("acme-2");
  });

  it("treats addresses case-insensitively and refuses duplicates as conflict", async () => {
    const first = await reg("Alice", "Alice@Example.com");
    expect(first.user.email).toBe("alice@example.com");
    let caught: unknown;
    try { await reg("Alice again", "alice@example.COM"); } catch (e) { caught = e; }
    expect(toAppError(caught).code).toBe("conflict");
    expect(getDb().select().from(users).all().length).toBe(1);
    expect(getDb().select().from(organizations).all().length).toBe(1);
    expect((await userRepo.findUserByEmail("ALICE@example.com"))?.id).toBe(first.user.id);
  });

  it("throttles sign-up once per attempt with rate_limited and writes nothing", async () => {
    let denied: unknown;
    for (let i = 0; i < 40; i += 1) {
      try { await reg(`Person ${i}`); } catch (e) { denied = e; break; }
    }
    expect(toAppError(denied).code).toBe("rate_limited");
    expect(getDb().select().from(users).all().length).toBeLessThan(40);
  });

  it("maps a throttled sign-in to rate_limited and charges the bucket once", async () => {
    await reg("Bob", "bob@example.com");
    resetRateLimits();
    let caught: unknown;
    for (let i = 0; i < 100; i += 1) {
      try { await authService.login({ email: "bob@example.com", password: "wrong", rememberMe: false }); }
      catch (e) { caught = e; if (toAppError(e).code === "rate_limited") break; }
    }
    expect(toAppError(caught).code).toBe("rate_limited");
  });

  it("signs in with a differently-cased address", async () => {
    await reg("Carol", "Carol@Example.com");
    const { user } = await authService.login({ email: "CAROL@example.com", password: PW, rememberMe: false } as never);
    expect(user.email).toBe("carol@example.com");
  });
});
EOF
